// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= type(uint120).max);
        address owner = c.owner();
        vm.deal(owner, 0);
        vm.deal(address(c), amount);
        uint256 ownerBalanceBefore = owner.balance;
        bool ok;
        vm.prank(owner);
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        uint256 ownerBalanceAfter = owner.balance;
        assertTrue((ok && address(c).balance == 0 && ownerBalanceAfter == ownerBalanceBefore + amount) || (!ok && address(c).balance == amount && ownerBalanceAfter == ownerBalanceBefore));
    }
}
